(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-029":{scenario:{company:"Tidewave Apps Studio",supervisor:{name:"Tạ Quang Vinh",role:{vi:"Trưởng nhóm Phát triển Di động",en:"Mobile Engineering Lead"}},ref_code:"REL-3124",title:{vi:"Lưu token an toàn. Đánh số bản dựng đúng. Phát hành sạch.",en:"Secure tokens. Correct build numbers. Clean release."},brief:{vi:"Bạn chuẩn bị bản phát hành REL-3124 (phiên bản 3.12.4) của ứng dụng ví điểm thưởng viết bằng Flutter. Pipeline CI báo hai lỗi: cửa hàng ứng dụng từ chối tải lên vì versionCode đã được dùng, và bản quét bảo mật phát hiện token đăng nhập lưu dạng rõ. Đối chiếu cấu hình nháp với chính sách phát hành đã duyệt, sửa nơi lưu token và versionCode, rồi lập báo cáo có căn cứ.",en:"You are preparing release REL-3124 (version 3.12.4) of a Flutter rewards wallet app. CI reports two failures: the app store rejected the upload because the versionCode was already used, and the security scan found the login token stored in plain text. Compare the draft config with the approved release policy, fix the token storage and the versionCode, then write an evidence-based report."},reference_title:{vi:"Chính sách phát hành & bảo mật đã duyệt · REL-3124",en:"Approved release & security policy · REL-3124"},fields:[{id:"TOKEN_STORE",label:{vi:"Nơi lưu access token",en:"Access token storage"},initial:"SharedPreferences",expected:"Keystore/Keychain",choices:["SharedPreferences","Keystore/Keychain","SQLite"],reference:"Mục MASVS-STORAGE",hint:{vi:"Dữ liệu xác thực phải nằm trong kho khóa an toàn do hệ điều hành bảo vệ, không lưu dạng rõ trong tệp cấu hình.",en:"Credentials must live in the OS-protected secure key store, never in plain-text preference files."}},{id:"VERSION_CODE",label:{vi:"versionCode của bản dựng",en:"Build versionCode"},initial:"31104",expected:"31204",reference:"Quy tắc đánh số bản dựng",ref_value:{vi:"Phiên bản 3.12.4; versionCode = MAJOR x 10000 + MINOR x 100 + PATCH",en:"Version 3.12.4; versionCode = MAJOR x 10000 + MINOR x 100 + PATCH"},hint:{vi:"versionCode phải tính từ đúng số phiên bản của bản phát hành này, không chép lại từ bản trước.",en:"Derive the versionCode from this release's version number, never copy it from the previous build."}}],sop32:{vi:"versionCode = MAJOR x 10000 + MINOR x 100 + PATCH của phiên bản đang phát hành; giá trị phải lớn hơn mọi bản đã tải lên cửa hàng và không bao giờ dùng lại.",en:"versionCode = MAJOR x 10000 + MINOR x 100 + PATCH of the version being released; it must exceed every build already uploaded and is never reused."},context:{label:"CI PIPELINE / REL-3124",metrics:[{label:{vi:"Phiên bản phát hành",en:"Release version"},value:"3.12.4"},{label:{vi:"versionCode bản trước",en:"Previous versionCode"},value:"31104"},{label:{vi:"Kết quả quét MASVS",en:"MASVS scan result"},value:"1 FAIL"}]},crisis:{vi:"Trưởng nhóm marketing nhắn: “Gắn thêm SDK quảng cáo đọc danh bạ và vị trí người dùng vào bản này, đừng hiện hộp thoại xin quyền kẻo tụt chuyển đổi. Tối nay phát hành 100% luôn.”",en:"The marketing lead messages you: “Add the ad SDK that reads users' contacts and location to this build, and skip the permission dialog so conversion does not drop. Ship to 100% tonight.”"},options:{safe:{vi:"Từ chối thu thập danh bạ, vị trí khi chưa có sự đồng ý; báo trưởng nhóm và bộ phận bảo vệ dữ liệu, đề xuất luồng xin đồng ý rõ ràng và phát hành theo giai đoạn.",en:"Refuse to collect contacts or location without consent; inform the lead and the data protection team, and propose a clear consent flow with a staged rollout."},shortcut:{vi:"Gắn SDK, ẩn hộp thoại xin quyền và phát hành 100% cho kịp chiến dịch, có khiếu nại thì gỡ sau.",en:"Add the SDK, hide the permission dialog and ship to 100% for the campaign, remove it later if users complain."},wait:{vi:"Không phát hành, không phản hồi ai và chờ marketing tự quyết định.",en:"Do not release, reply to no one and wait for marketing to decide."}},questions:{vi:["Vì sao versionCode phải là 31204 và token phải lưu trong Keystore/Keychain? Bằng chứng nào từ log và chính sách hỗ trợ bạn?","Nếu một SDK bên thứ ba thu thập dữ liệu cá nhân, bạn kiểm soát rủi ro tuân thủ và rủi ro phát hành như thế nào?"],en:["Why must the versionCode be 31204 and the token be stored in Keystore/Keychain? Which log lines and policy items support you?","If a third-party SDK collects personal data, how do you control the compliance and release risks?"]},hints:{vi:["Chạy lệnh xem trạng thái pipeline và kết quả quét bảo mật trước khi sửa bất kỳ dòng cấu hình nào.","Tách số phiên bản thành MAJOR, MINOR, PATCH rồi áp công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi SDK mới thu thập dữ liệu cá nhân phải qua đánh giá quyền riêng tư và có sự đồng ý."],en:["Check the pipeline status and the security scan result before changing any config line.","Split the version into MAJOR, MINOR and PATCH, then apply the formula in SOP 3.2.","Re-read SOP 4.2: any new SDK that collects personal data needs a privacy review and user consent."]},terminal:{system:"mobile-ci",settable:["TOKEN_STORE","VERSION_CODE"],commands:[{cmd:"status",out:{vi:"Pipeline REL-3124: build OK; upload FAILED - cửa hàng báo versionCode 31104 đã được sử dụng; bước quét bảo mật: 1 FAIL.",en:"Pipeline REL-3124: build OK; upload FAILED - store says versionCode 31104 is already in use; security scan step: 1 FAIL."}},{cmd:"cat pubspec.yaml",out:{vi:"version: 3.12.4+31104 (tên phiên bản + số bản dựng); gói lưu trữ an toàn đã khai báo nhưng mã đăng nhập chưa dùng.",en:"version: 3.12.4+31104 (version name + build number); the secure storage package is declared but the login code does not use it."}},{cmd:"cat masvs_scan.txt",out:{vi:"MASVS-STORAGE-1 FAIL: access_token ghi dạng rõ trong tệp SharedPreferences. Khuyến nghị: lưu qua kho khóa an toàn của hệ điều hành.",en:"MASVS-STORAGE-1 FAIL: access_token written in plain text to the SharedPreferences file. Fix: store it through the OS secure key store."}},{cmd:"git log -3",out:{vi:"c41e9 release 3.11.4 build 31104 | 9ab02 feat: ví điểm v3.12 | 77d1c fix: đăng nhập sinh trắc học",en:"c41e9 release 3.11.4 build 31104 | 9ab02 feat: rewards wallet v3.12 | 77d1c fix: biometric login"}},{cmd:"cat release_policy.md",out:{vi:"Số bản dựng tăng dần, tính từ MAJOR.MINOR.PATCH; dữ liệu xác thực chỉ lưu trong kho khóa an toàn; SDK mới phải qua đánh giá quyền riêng tư.",en:"Build numbers only increase and are derived from MAJOR.MINOR.PATCH; credentials live only in the secure key store; new SDKs need a privacy review."}}]}},learning:{summary:{vi:"Lập trình viên ứng dụng di động thiết kế, xây dựng và vận hành ứng dụng trên iOS, Android hoặc đa nền tảng Flutter: từ giao diện, quản lý trạng thái, gọi API, lưu trữ cục bộ đến ký ứng dụng và phát hành lên cửa hàng. Giá trị tạo ra là trải nghiệm mượt, ổn định và an toàn cho dữ liệu người dùng. Công việc đòi hỏi tư duy kiến trúc, kiểm thử tự động, tối ưu hiệu năng và tuân thủ chính sách quyền riêng tư.",en:"A mobile developer designs, builds and runs apps on iOS, Android or cross-platform Flutter: from UI, state management, API calls and local storage to app signing and store release. The value delivered is a smooth, stable experience that keeps user data safe. The role requires architectural thinking, automated testing, performance tuning and compliance with privacy policies."},responsibilities:{vi:["Xây dựng màn hình, luồng điều hướng và quản lý trạng thái theo thiết kế đã duyệt.","Tích hợp API, xử lý lỗi mạng, bộ nhớ đệm và chế độ ngoại tuyến.","Bảo vệ dữ liệu người dùng: lưu trữ an toàn, mã hóa kênh truyền, xin quyền đúng mục đích.","Viết kiểm thử đơn vị, kiểm thử widget và tích hợp; duy trì pipeline CI/CD.","Ký ứng dụng, đánh số bản dựng, phát hành theo giai đoạn và theo dõi crash sau phát hành."],en:["Build screens, navigation flows and state management according to the approved design.","Integrate APIs and handle network errors, caching and offline mode.","Protect user data: secure storage, encrypted transport and purpose-bound permission requests.","Write unit, widget and integration tests and maintain the CI/CD pipeline.","Sign the app, number builds, run staged rollouts and monitor crashes after release."]},competencies:[{name:{vi:"Kiến trúc ứng dụng",en:"App architecture"},desc:{vi:"Tách lớp giao diện, nghiệp vụ, dữ liệu (MVVM, Clean Architecture, BLoC) để dễ kiểm thử và bảo trì.",en:"Separate UI, domain and data layers (MVVM, Clean Architecture, BLoC) for testability and maintenance."}},{name:{vi:"Bảo mật di động",en:"Mobile security"},desc:{vi:"Áp dụng MASVS: lưu trữ an toàn, chống giả mạo chứng chỉ, không ghi bí mật vào mã nguồn hay log.",en:"Apply MASVS: secure storage, certificate validation, no secrets in source code or logs."}},{name:{vi:"Hiệu năng & ổn định",en:"Performance & stability"},desc:{vi:"Đo khung hình, bộ nhớ, thời gian khởi động; xử lý crash và ANR dựa trên dữ liệu thực tế.",en:"Measure frame rate, memory and startup time; fix crashes and ANRs from field data."}},{name:{vi:"Phát hành & CI/CD",en:"Release & CI/CD"},desc:{vi:"Tự động build, ký, kiểm thử và phát hành theo giai đoạn với số bản dựng tăng dần.",en:"Automate build, signing, testing and staged rollout with ever-increasing build numbers."}},{name:{vi:"Quyền riêng tư & đạo đức",en:"Privacy & ethics"},desc:{vi:"Chỉ thu thập dữ liệu cần thiết, có sự đồng ý; từ chối tính năng theo dõi ngầm người dùng.",en:"Collect only necessary data with consent and refuse features that covertly track users."}}],knowledge:{vi:["OWASP MASVS và MASTG: tiêu chuẩn xác minh và hướng dẫn kiểm thử bảo mật ứng dụng di động.","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân: sự đồng ý, mục đích xử lý, quyền của chủ thể dữ liệu.","Hướng dẫn giao diện của từng nền tảng (Human Interface Guidelines cho iOS, Material Design cho Android).","Vòng đời ứng dụng, quản lý trạng thái, luồng bất đồng bộ (async/await, Stream) trong Flutter và mã gốc.","Chính sách cửa hàng ứng dụng: khai báo quyền riêng tư, ký ứng dụng, số bản dựng tăng dần, phát hành theo giai đoạn."],en:["OWASP MASVS and MASTG: the mobile app security verification standard and testing guide.","Vietnam Decree 13/2023/ND-CP on personal data protection: consent, processing purpose and data subject rights.","Platform UI guidelines (Human Interface Guidelines for iOS, Material Design for Android).","App lifecycle, state management and async flows (async/await, Streams) in Flutter and native code.","App store policies: privacy declarations, app signing, increasing build numbers and staged rollouts."]},tools:["Flutter SDK & Dart","Xcode / Android Studio","Git","Fastlane","Công cụ theo dõi crash","Postman"],kpis:{vi:["Tỷ lệ người dùng không gặp crash (crash-free users) sau mỗi bản phát hành.","Thời gian khởi động nguội và tỷ lệ khung hình bị giật.","Số lỗi bảo mật mức cao trong bản quét MASVS (mục tiêu bằng 0).","Điểm đánh giá trên cửa hàng và tỷ lệ bản phát hành không phải rút lại."],en:["Crash-free users rate after each release.","Cold start time and janky frame rate.","High-severity findings in the MASVS scan (target zero).","Store rating and share of releases that never need a rollback."]},day:[{time:"08:30",vi:"Xem bảng crash và đánh giá mới của bản phát hành hôm qua, tạo ticket cho lỗi nặng.",en:"Review crash dashboards and new store reviews for yesterday's release and ticket severe issues."},{time:"09:15",vi:"Họp nhanh đầu ngày với nhóm sản phẩm, thống nhất ưu tiên sprint.",en:"Join the daily stand-up with the product team and agree on sprint priorities."},{time:"10:00",vi:"Lập trình màn hình thanh toán mới, viết kiểm thử widget song song.",en:"Build the new payment screen and write widget tests alongside."},{time:"14:00",vi:"Rà soát mã của đồng nghiệp, kiểm tra cách lưu token và xử lý quyền.",en:"Review a teammate's pull request, checking token storage and permission handling."},{time:"16:30",vi:"Chạy pipeline phát hành nội bộ, kiểm tra số bản dựng và gửi bản thử cho QA.",en:"Run the internal release pipeline, check the build number and send a test build to QA."}],mistakes:{vi:["Lưu token, mật khẩu hoặc khóa API dạng rõ trong SharedPreferences, UserDefaults hay mã nguồn.","Chép lại số bản dựng của bản trước khiến cửa hàng từ chối tải lên.","Tắt kiểm tra chứng chỉ SSL khi gỡ lỗi rồi quên bật lại trước khi phát hành."],en:["Storing tokens, passwords or API keys in plain text in SharedPreferences, UserDefaults or source code.","Copying the previous build number so the store rejects the upload.","Disabling SSL certificate checks while debugging and forgetting to re-enable them before release."]},career:[{vi:"Lập trình viên di động tập sự",en:"Junior mobile developer"},{vi:"Lập trình viên di động",en:"Mobile developer"},{vi:"Lập trình viên di động cấp cao / trưởng nhóm kỹ thuật",en:"Senior mobile developer / tech lead"},{vi:"Kiến trúc sư ứng dụng di động / quản lý kỹ thuật",en:"Mobile architect / engineering manager"}],glossary:[{term:"versionCode / build number",vi:"Số nguyên tăng dần định danh từng bản dựng trên cửa hàng, khác với tên phiên bản hiển thị.",en:"Increasing integer that identifies each build on the store, separate from the display version name."},{term:"Keystore / Keychain",vi:"Kho khóa an toàn của Android và iOS, bảo vệ khóa và bí mật bằng cơ chế của hệ điều hành.",en:"Android and iOS secure stores that protect keys and secrets with operating system mechanisms."},{term:"MASVS",vi:"Tiêu chuẩn xác minh bảo mật ứng dụng di động của OWASP, chia theo nhóm lưu trữ, mạng, xác thực...",en:"OWASP mobile app security verification standard, grouped into storage, network, authentication and more."},{term:"Staged rollout",vi:"Phát hành dần theo tỷ lệ người dùng để phát hiện lỗi sớm và dừng kịp thời.",en:"Releasing to a growing share of users to catch issues early and halt in time."},{term:"ANR",vi:"Lỗi ứng dụng Android không phản hồi khi luồng giao diện bị chặn quá lâu.",en:"Android Application Not Responding error when the UI thread is blocked too long."}],quiz:[{q:{vi:"Theo công thức MAJOR x 10000 + MINOR x 100 + PATCH, phiên bản 2.7.15 có versionCode bao nhiêu?",en:"Using MAJOR x 10000 + MINOR x 100 + PATCH, what is the versionCode of version 2.7.15?"},options:{vi:["20715","27150","2715","20800"],en:["20715","27150","2715","20800"]},answer:0,explain:{vi:"2 x 10000 + 7 x 100 + 15 = 20715; giá trị phải lớn hơn mọi bản đã tải lên.",en:"2 x 10000 + 7 x 100 + 15 = 20715; it must exceed every build already uploaded."}},{q:{vi:"Nơi phù hợp để lưu refresh token trên thiết bị là đâu?",en:"Where should a refresh token be stored on the device?"},options:{vi:["Tệp văn bản trong bộ nhớ ngoài","SharedPreferences hoặc UserDefaults dạng rõ","Kho khóa an toàn của hệ điều hành (Keystore/Keychain)","Hằng số trong mã nguồn"],en:["A text file on external storage","Plain SharedPreferences or UserDefaults","The OS secure key store (Keystore/Keychain)","A constant in the source code"]},answer:2,explain:{vi:"MASVS yêu cầu bí mật xác thực được bảo vệ bởi kho khóa an toàn của hệ điều hành.",en:"MASVS requires authentication secrets to be protected by the OS secure key store."}},{q:{vi:"Marketing yêu cầu đọc danh bạ người dùng mà không hiện hộp thoại xin quyền. Bạn làm gì?",en:"Marketing asks you to read users' contacts without showing a permission dialog. What do you do?"},options:{vi:["Làm theo vì đây là yêu cầu kinh doanh","Làm ngầm rồi cập nhật chính sách sau","Chờ người dùng khiếu nại mới xử lý","Từ chối, báo trưởng nhóm và bộ phận bảo vệ dữ liệu, đề xuất luồng xin đồng ý"],en:["Comply because it is a business request","Do it silently and update the policy later","Wait for user complaints before acting","Refuse, escalate to the lead and data protection team, propose a consent flow"]},answer:3,explain:{vi:"Xử lý dữ liệu cá nhân cần sự đồng ý và mục đích rõ ràng; thu thập ngầm vi phạm pháp luật và chính sách cửa hàng.",en:"Processing personal data needs consent and a clear purpose; covert collection breaks the law and store policy."}},{q:{vi:"Để đạt 60 khung hình/giây, mỗi khung hình phải dựng xong trong khoảng bao lâu?",en:"To reach 60 frames per second, roughly how long can each frame take to render?"},options:{vi:["6 ms","16,7 ms","33,3 ms","60 ms"],en:["6 ms","16.7 ms","33.3 ms","60 ms"]},answer:1,explain:{vi:"1000 ms / 60 khung hình ≈ 16,7 ms; vượt ngưỡng này giao diện sẽ bị giật.",en:"1000 ms / 60 frames ≈ 16.7 ms; going over it causes visible jank."}}],tools_en:["Flutter SDK & Dart","Xcode / Android Studio","Git","Fastlane","Crash reporting tools","Postman"]}}})})(window.KKR);
